 const configurations=[['C',6,'2p',2],['N',7,'2p',3],['O',8,'2p',4],['F',9,'2p',5],['Ne',10,'2p',6],['Na',11,'3s',1],['Mg',12,'3s',2],['Al',13,'3p',1],['P',15,'3p',3],['S',16,'3p',4],['Cl',17,'3p',5],['Ar',18,'3p',6]];
